[SharpProof.Attributes.ContractFor(typeof(Algorithms.Numeric.GreatestCommonDivisor))]
internal static class GreatestCommonDivisorContracts
{
    public static int FindGCDEuclidean(int a, int b)
    {
        SharpProof.Attributes.Contract.Ensures(SharpProof.Attributes.Contract.Result<int>() >= 0);
        return default!;
    }
    private static int Stein(int a, int b)
    {
        SharpProof.Attributes.Contract.Requires(a >= 0 && b >= 0);
        SharpProof.Attributes.Contract.Ensures(SharpProof.Attributes.Contract.Result<int>() >= 0);
        return default!;
    }
}
